state.bids.activeBidTaxonomyType = "category";
state.bids.activeBidTaxonomyTarget = "single";
state.shared.activeStandardAnswerTarget = "single";
state.shared.activeStandardAnswerMode = "answer";
state.bids.activeBidderTarget = "single";
state.shared.activeBatchRowId = null;
state.shared.currentOpenedProjectEmailId = null;
state.bids.bidBatchItems = [];
state.bids.editingBidAnswerVariants = [];
state.bids.editingBidderId = null;
state.documents.documentTemplates = [];
state.documents.documentBlocks = [];
state.documents.editingDocumentTemplateId = null;
state.documents.editingDocumentBlockId = null;
state.shared.EMAIL_TAGS = new Set(["P","BR","STRONG","EM","UL","OL","LI","A"]);
state.library.templateInsertTarget = "body";
state.shared.savedEditorRanges = new WeakMap();
state.shared.editorHistories = new WeakMap();
state.library.tplSubject.addEventListener("focus",()=>state.library.templateInsertTarget="subject");
state.library.tplBody.addEventListener("focus",()=>state.library.templateInsertTarget="body");
state.library.tplNoticeBody.addEventListener("focus",()=>state.library.templateInsertTarget="notice");
state.library.tplSubject.addEventListener("input",actions.validateTemplatePlaceholders);
[state.library.tplName,state.library.tplCategory].forEach(input=>input.addEventListener("input",actions.validateTemplatePlaceholders));
[state.library.tplBody,state.mail.resultBody,state.library.tplNoticeBody].forEach(editor=>{
  editor.addEventListener("keyup",()=>actions.rememberEditorSelection(editor));
  editor.addEventListener("mouseup",()=>actions.rememberEditorSelection(editor));
  editor.addEventListener("input",()=>actions.recordEditorHistory(editor));
  editor.addEventListener("keydown",event=>{
    const key=event.key.toLowerCase();
    if((event.ctrlKey||event.metaKey)&&!event.altKey&&(key==="b"||key==="i")){
      event.preventDefault();actions.rememberEditorSelection(editor);actions.formatEditor(editor.id,key==="b"?"bold":"italic");
    }
  });
  if(editor!==state.mail.resultBody)editor.addEventListener("input",actions.validateTemplatePlaceholders);
  // Do not replace the DOM on blur: dialogs must retain the insertion range.
  // Paste, loading, saving and exporting still pass through the sanitizers.
  editor.addEventListener("blur",()=>actions.rememberEditorSelection(editor));
  if(editor!==state.library.tplNoticeBody)editor.addEventListener("click",event=>{
    if(event.target.tagName==="IMG")actions.openEmailImageDialog(editor.id,event.target);
  });
  actions.resetEditorHistory(editor);
});
document.addEventListener("click",event=>{
  document.querySelectorAll(".template-actions-menu[open]").forEach(menu=>{
    if(!menu.contains(event.target))menu.removeAttribute("open");
  });
});
state.shared.params = new URLSearchParams(location.search);
if(state.shared.params.get("login_error")){
  const retry=Number(state.shared.params.get("retry")||0);
  state.shared.byId("loginError").textContent=state.shared.params.get("login_error")==="locked"
    ?`Das Konto ist vorübergehend gesperrt. Erneuter Versuch in ${retry} Sekunden.`
    :"Die Anmeldung ist fehlgeschlagen. Bitte Benutzername und Passwort prüfen.";
  state.shared.byId("loginError").hidden=false;
}
if(state.shared.byId("loginNext"))state.shared.byId("loginNext").value=(/^\/(?:vorlage\/\d+|app\/[a-z-]+(?:\/\d+)?)$/.test(location.pathname)||location.pathname==="/excel-import")?location.pathname:"/";
if(state.auth.forcedPasswordDialog)state.auth.forcedPasswordDialog.addEventListener("cancel",event=>event.preventDefault());
// Compatibility adapters are derived from the single page registry.
state.shared.MODULE_REGISTRY = Object.fromEntries(Object.entries(groups).map(([id,label])=>[id,{label,tabs:pages.filter(page=>page.group===id).map(page=>page.id)}]));
state.shared.TAB_MODULES = Object.fromEntries(pages.map(page=>[page.id,page.group]));
state.shared.MODULE_DEFAULTS = Object.fromEntries(Object.keys(groups).map(group=>[group,pages.filter(page=>page.group===group&&page.listed).map(page=>page.id)]));
state.shared.INTERNAL_QUICKLINKS = pages.filter(page=>page.listed).map(page=>({target:page.id,label:page.title,anyPermission:page.permissions}));
state.bids.editingBidQuestionId = null;
state.documents.documentAnalysis = null;
state.documents.documentFieldRequest = 0;
state.documents.documentEditRequest = 0;
state.documents.documentInputRevision = 0;
state.documents.documentPickerTarget = "template";
state.documents.documentPdfAvailable = false;
state.documents.documentBusy = false;
state.shared.activeEmailImageEditor = null;
state.shared.activeEmailImage = null;
state.shared.emailImageData = null;
state.shared.imageUploadRevision = 0;
state.shared.pendingImageExportAction = null;
state.bids.bidWorkbookPreviewState = null;
state.shared.pendingApiKeyAction = null;
initializeShell();
WveDrafts.register('tab-bid-answer-create',{get:()=>structuredClone(state.bids.editingBidAnswerVariants),set:value=>{state.bids.editingBidAnswerVariants=structuredClone(value);actions.renderBidAnswerVariants()}});
WveDrafts.register('tab-bid-question-batch',{get:()=>structuredClone(state.bids.bidBatchItems),set:value=>{state.bids.bidBatchItems=structuredClone(value);actions.renderBidBatchRows()}});
WveDrafts.register('tab-generator',{
  get:()=>({generated:state.mail.emailGenerated,dirty:state.mail.resultDirty,result:structuredClone(state.mail.resultContext),
    mode:state.mail.mode.value,project:state.projects.projectSelect.value,contact:state.projects.contactSelect.value,template:state.library.templateSelect.value}),
  set:value=>{
    state.mail.emailGenerated=value.generated;state.mail.resultDirty=value.dirty;state.mail.resultContext=structuredClone(value.result);
    state.mail.mode.value=value.mode;state.projects.projectSelect.value=value.project;state.library.templateSelect.value=value.template;
    actions.refreshContacts();state.projects.contactSelect.value=value.contact;actions.renderManualFields(true);
  }
});
WveDrafts.register('tab-project-edit',{get:()=>({data:structuredClone(state.projects.editingProjectData),revision:state.projects.editingProjectRevision}),set:value=>{state.projects.editingProjectData=structuredClone(value.data);state.projects.editingProjectRevision=value.revision}});
WveDrafts.register('contactDialog',{get:()=>structuredClone(state.projects.editingContactProject),set:value=>{state.projects.editingContactProject=structuredClone(value)}});
WveDrafts.register('tab-template-edit',{get:()=>structuredClone(state.library.editingFields),set:value=>{state.library.editingFields=structuredClone(value);actions.renderFieldEditor()}});
WveDrafts.register('tab-settings',{get:()=>({logo:state.shared.pendingLogoData,order:structuredClone(state.shared.appSettings.navigation_areas)}),set:value=>{state.shared.pendingLogoData=value.logo;state.shared.appSettings.navigation_areas=value.order;actions.renderNavigationOrderEditor()}});
document.addEventListener('wve:draft-restored',event=>{
  if(event.detail==='tab-generator'){
    const value=state.mail.mode.value;
    state.mail.modeProjectButton.classList.toggle('active',value==='project');state.mail.modeManualButton.classList.toggle('active',value==='manual');state.projects.projectSelectWrap.hidden=value!=='project';
    actions.updateProjectPickerButton();actions.updateTemplatePickerButton();actions.updatePlaceholderWarning();actions.updateSaveProjectEmailButton();
  }
  if(event.detail==='tab-template-edit')actions.toggleTemplateNoticeEditor();
  if(event.detail==='tab-bid-question-create'){
    actions.updateBidProjectButton('single');actions.updateSingleBidTaxonomyButtons();actions.updateSingleBidderButton();
  }
});
actions.loadPublicSettings();
actions.boot();
